'use strict';

const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { spawnSync } = require('child_process');

const workspace = process.env.GITHUB_WORKSPACE || process.cwd();
const evidenceDir = process.env.A01_EVIDENCE_DIR || path.join(process.env.RUNNER_TEMP || workspace, 'book-system-e2e-authority-guards-evidence');
fs.mkdirSync(evidenceDir, { recursive:true });

const rel = {
  contract:'qualification/book-system/end-to-end-authoring-001/BOOK-SYSTEM-E2E-AUTHORITY-GUARDS-001.json',
  authorFinding:'qualification/book-system/end-to-end-authoring-001/BOOK-SYSTEM-E2E-AUTHOR-DECISION-CURRENT-SUBJECT-GAP-001.json',
  freezeFinding:'qualification/book-system/end-to-end-authoring-001/BOOK-SYSTEM-E2E-EXPORT-FREEZE-PARENT-ADMISSION-GAP-001.json',
  authorBase:'system-master/book-system/author-decision-queue.js',
  authorGuard:'system-master/book-system/author-decision-current-subject-guard.js',
  exportBase:'system-master/book-system/export-freeze.js',
  exportGuard:'system-master/book-system/export-freeze-parent-admission-guard.js',
  exportFixtures:'qualification/book-system/export-freeze-001/BOOK-SYSTEM-EXPORT-FREEZE-001-RECONCILED-FIXTURES.json',
  qualifier:'.github/scripts/book-system-e2e-authority-guards-001-qualify.js',
};
const contract=JSON.parse(fs.readFileSync(path.join(workspace,rel.contract),'utf8'));
const authorFinding=JSON.parse(fs.readFileSync(path.join(workspace,rel.authorFinding),'utf8'));
const freezeFinding=JSON.parse(fs.readFileSync(path.join(workspace,rel.freezeFinding),'utf8'));
const fixtures=JSON.parse(fs.readFileSync(path.join(workspace,rel.exportFixtures),'utf8'));
const baseAuthor=require(path.join(workspace,rel.authorBase));
const author=require(path.join(workspace,rel.authorGuard));
const baseFreeze=require(path.join(workspace,rel.exportBase));
const freeze=require(path.join(workspace,rel.exportGuard));
const vr=require(path.join(workspace,'system-master/book-system/version-and-rollback.js'));

function clone(v){return v===undefined?undefined:JSON.parse(JSON.stringify(v));}
function assert(ok,code,detail=''){if(!ok)throw Object.assign(new Error(detail?`${code}:${detail}`:code),{code});}
function expectError(fn,code){try{fn();}catch(e){assert(e&&e.code===code,'WRONG_ERROR_CODE',`expected=${code}:actual=${e&&e.code}:detail=${e&&e.message}`);return e;}assert(false,'EXPECTED_ERROR_NOT_THROWN',code);}
function git(args,encoding='utf8'){return spawnSync('git',['-c',`safe.directory=${workspace}`,...args],{cwd:workspace,encoding,windowsHide:true,shell:false});}
function head(){const r=git(['rev-parse','HEAD']);assert(r.status===0,'GIT_HEAD_FAILED');return r.stdout.trim();}
function sameHistoricalBytes(sha,p){const a=git(['show',`${sha}:${p}`],null),b=git(['show',`HEAD:${p}`],null);assert(a.status===0&&b.status===0,'GIT_SHOW_FAILED',p);return Buffer.compare(a.stdout||Buffer.alloc(0),b.stdout||Buffer.alloc(0))===0;}
function fileSha(p){return crypto.createHash('sha256').update(fs.readFileSync(path.join(workspace,p))).digest('hex');}
function write(n,v){fs.writeFileSync(path.join(evidenceDir,n),typeof v==='string'?v:JSON.stringify(v,null,2),'utf8');}
function currentBindings(l){return clone(l.state_snapshots[l.current_snapshot_id].active_version_bindings);}
function manuscriptRecord(parent){const r=vr.objectRecords(parent).find(x=>x.type==='MANUSCRIPT_MANIFEST'&&(parent.active.canonical_manuscript_ref===x.object_id||parent.active.canonical_manuscript_ref===`${x.object_id}:${x.object_version}`));assert(r,'ACTIVE_MANUSCRIPT_NOT_FOUND');return r;}
function manuscriptIdentity(parent){const r=manuscriptRecord(parent);return {object_id:r.object_id,object_version:String(r.object_version),object_digest:r.object_digest};}
function authorSetup(){const p=clone(fixtures.base_parent_state);delete p.state_digest;p.state_version=1;p.book_project.status='AUTHOR_REVIEW';p.author_decisions=[];p.export_releases=[];const init=vr.createVersionLedger(vr.sealState(p));return {parent:init.parent_state,versionLedger:init.version_ledger,queueLedger:author.createQueueLedger(init.parent_state)};}
function options(){return [{option_id:'APPROVE',label:'Approve',effect:'Approve synthetic qualification choice',consequence_class:'FINALIZATION',canonical_decision_status:'APPROVED'},{option_id:'REJECT',label:'Reject',effect:'Reject synthetic qualification choice',consequence_class:'ROUTINE_REVERSIBLE',canonical_decision_status:'REJECTED'}];}
function enqueueRequest(s,id='AG'){return {enqueue_request_id:`${id}-ENQ`,idempotency_key:`${id}-ENQ-IDEM`,actor_class:'PARENT_SYSTEM',expected_parent_state_version:s.parent.state_version,expected_parent_state_digest:s.parent.state_digest,expected_queue_ledger_version:s.queueLedger.queue_ledger_version,expected_queue_ledger_digest:author.digestQueueLedger(s.queueLedger),source_authority_kind:'PARENT_DIRECT_AUTHOR_QUERY',source_handoff_refs:[`SYNTHETIC:${id}`],decision_type:'FINALIZATION_APPROVAL',subject_ref:s.parent.active.canonical_manuscript_ref,subject_identity_refs:[manuscriptIdentity(s.parent)],options:options(),custom_option_allowed:false,evidence_refs:[`SYNTHETIC:${id}:EVIDENCE`],disagreement_refs:[],consequence_summary:'Synthetic guard qualification only.',confirmation_policy:'REVIEW_SELECTED_CHOICE',created_at:'2026-09-09T23:00:00Z'};}
function enqueue(s,id='AG'){const request=enqueueRequest(s,id);const out=author.enqueueDecision({parentState:s.parent,queueLedger:s.queueLedger,request});return {...s,queueLedger:out.queue_ledger,decisionRequest:out.decision_request,enqueueRequest:request};}
function resolutionRequest(s,id='AG'){const snap=s.decisionRequest;return {resolution_request_id:`${id}-RESOLVE`,idempotency_key:`${id}-RESOLVE-IDEM`,author_actor_ref:'SYNTHETIC-AUTHOR-GUARD-FIXTURE',author_authority_proof_ref:'SYNTHETIC-AUTHORITY-PROOF-GUARD-FIXTURE',expected_parent_state_version:s.parent.state_version,expected_parent_state_digest:s.parent.state_digest,expected_queue_ledger_version:s.queueLedger.queue_ledger_version,expected_queue_ledger_digest:author.digestQueueLedger(s.queueLedger),decision_request_id:snap.decision_request_id,expected_decision_request_version:snap.decision_request_version,expected_decision_request_digest:author.digestDecisionRequest(snap),selected_option_id:'APPROVE',custom_author_choice:null,confirmation_evidence:{confirmed:true,decision_request_digest:author.digestDecisionRequest(snap),selected_option_identity:'OPTION:APPROVE',consequence_reviewed:false,confirmation_evidence_ref:`SYNTHETIC:${id}:CONFIRM`},rationale_optional:'SYNTHETIC_GUARD_FIXTURE_NOT_REAL_AUTHOR_AUTHORITY',resolved_at:'2026-09-09T23:01:00Z'};}
function changedManuscript(s,id='AG-CHANGE'){const pre=s.parent,proposed=clone(pre),old=manuscriptRecord(pre);proposed.manuscripts.push({manuscript_id:old.object_id,version_id:'V2',artifact_digest:'b'.repeat(64),authority_state:'CANONICAL',parent_version_ref:`${old.object_id}:${old.object_version}`,change_set_ref:`${id}-SET`,created_by:'BOOK_SYSTEM_PARENT',created_at:'2026-09-09T23:02:00Z'});proposed.active.canonical_manuscript_ref=`${old.object_id}:V2`;const preview=vr.sealState({...proposed,state_version:pre.state_version+1});const nr=vr.objectRecords(preview).find(x=>x.type==='MANUSCRIPT_MANIFEST'&&x.object_version==='V2');const bindings=currentBindings(s.versionLedger);bindings.canonical_manuscript_ref=nr.node_id;const out=vr.commitSuccessor({parentState:pre,versionLedger:s.versionLedger,request:{request_id:id,idempotency_key:`${id}-IDEM`,actor_class:'PARENT_SYSTEM',expected_state_version:pre.state_version,expected_state_digest:pre.state_digest,expected_ledger_version:s.versionLedger.ledger_version,expected_ledger_digest:vr.digestLedger(s.versionLedger),proposed_parent_state:proposed,active_version_bindings:bindings,evidence_refs:[`SYNTHETIC:${id}`],author_decision_refs:[],lifecycle_transition_receipt:null}});return {...s,parent:out.parent_state,versionLedger:out.version_ledger,changeReceipt:out.receipt,previousParent:pre};}
function revalidate(oldState,newState,id='AG-REVAL'){return author.revalidateAgainstParent({previousParentState:oldState.parent,currentParentState:newState.parent,queueLedger:oldState.queueLedger,request:{revalidation_request_id:id,idempotency_key:`${id}-IDEM`,actor_class:'PARENT_SYSTEM',expected_queue_ledger_version:oldState.queueLedger.queue_ledger_version,expected_queue_ledger_digest:author.digestQueueLedger(oldState.queueLedger),revalidation_evidence_refs:[`SYNTHETIC:${id}:EVIDENCE`],revalidated_at:'2026-09-09T23:03:00Z'}});}
function freezeSetup(){const parent=vr.sealState(clone(fixtures.base_parent_state));const ledger=freeze.createFreezeLedger(parent);return {parent,ledger};}
function freezeRequest(s,id='FG'){const r=clone(fixtures.base_request);r.freeze_request_id=`${id}-REQ`;r.idempotency_key=`${id}-IDEM`;r.release_id=`${id}-RELEASE`;r.expected_parent_state_version=s.parent.state_version;r.expected_parent_state_digest=s.parent.state_digest;r.expected_freeze_ledger_version=s.ledger.ledger_version;r.expected_freeze_ledger_digest=freeze.digestFreezeLedger(s.ledger);return r;}

const tests={};function test(id,fn){tests[id]=fn;}
test('G001_CONTRACT_AND_TWO_FINDINGS_BOUND',()=>{assert(contract.repairs.length===2,'REPAIR_COUNT');assert(authorFinding.selected_repair.id===author.GUARD_ID,'AUTHOR_FINDING_MISMATCH');assert(freezeFinding.selected_repair.id===freeze.GUARD_ID,'FREEZE_FINDING_MISMATCH');});
test('G002_AUTHOR_V1_BYTES_UNCHANGED',()=>assert(sameHistoricalBytes('9601ae5df8348c1daac8805eaefa1718c431dd49',rel.authorBase),'AUTHOR_V1_BYTES_CHANGED'));
test('G003_EXPORT_FREEZE_V1_BYTES_UNCHANGED',()=>assert(sameHistoricalBytes('0bc1f96ed0b8effd22c432a7d727fd13d613b825',rel.exportBase),'EXPORT_V1_BYTES_CHANGED'));
test('G004_ACTIVE_GOVERNED_SUBJECT_IS_CURRENT',()=>{const s=authorSetup();assert(author.strictSubjectCurrent(s.parent,[manuscriptIdentity(s.parent)])===true,'ACTIVE_SUBJECT_REJECTED');});
test('G005_HISTORICAL_GOVERNED_SUBJECT_IS_NOT_CURRENT',()=>{const s=enqueue(authorSetup(),'G005');const oldId=clone(s.decisionRequest.subject_identity_refs);const changed=changedManuscript(s,'G005-CHANGE');assert(author.strictSubjectCurrent(changed.parent,oldId)===false,'HISTORICAL_SUBJECT_ACCEPTED');});
test('G006_HISTORICAL_SUBJECT_NEW_ENQUEUE_REJECTED',()=>{let s=authorSetup();const old=manuscriptIdentity(s.parent);s=changedManuscript(s,'G006-CHANGE');s.queueLedger=author.createQueueLedger(s.parent);const req=enqueueRequest(s,'G006');req.subject_ref='MANUSCRIPT-001:V1';req.subject_identity_refs=[old];expectError(()=>author.enqueueDecision({parentState:s.parent,queueLedger:s.queueLedger,request:req}),'AUTHOR_DECISION_SUBJECT_NOT_CURRENT');});
test('G007_CHANGED_SUBJECT_REVALIDATION_EFFECTIVELY_STALES_REQUEST',()=>{const old=enqueue(authorSetup(),'G007');const changed=changedManuscript(old,'G007-CHANGE');const out=revalidate(old,changed,'G007-REVAL');const currentId=out.queue_ledger.current_request_index[Object.keys(out.queue_ledger.current_request_index)[0]];assert(out.disposition==='REVALIDATED_WITH_STRICT_STALENESS','STRICT_REVALIDATION_DISPOSITION');assert(author.effectiveDecisionState(out.queue_ledger,currentId)==='STALE','EFFECTIVE_STALE_MISSING');assert(out.strict_stale_request_ids.includes(currentId),'STRICT_STALE_INDEX_MISSING');});
test('G008_REVALIDATION_PRESERVES_BASE_QUEUE_HISTORY',()=>{const old=enqueue(authorSetup(),'G008');const before=Object.keys(old.queueLedger.decision_request_snapshots);const changed=changedManuscript(old,'G008-CHANGE');const out=revalidate(old,changed,'G008-REVAL');for(const id of before)assert(out.queue_ledger.decision_request_snapshots[id],'OLD_QUEUE_HISTORY_REMOVED');assert(out.queue_ledger.bound_parent_state_digest===changed.parent.state_digest,'QUEUE_NOT_REBOUND');});
test('G009_HISTORICAL_SUBJECT_RESOLUTION_REJECTED_WITHOUT_REVALIDATION',()=>{const old=enqueue(authorSetup(),'G009');const changed=changedManuscript(old,'G009-CHANGE');const rr=resolutionRequest(old,'G009');expectError(()=>author.resolveDecision({parentState:changed.parent,versionLedger:changed.versionLedger,queueLedger:old.queueLedger,request:rr}),'AUTHOR_DECISION_SUBJECT_NOT_CURRENT');});
test('G010_OVERLAY_STALE_SUBJECT_RESOLUTION_REJECTED',()=>{const old=enqueue(authorSetup(),'G010');const changed=changedManuscript(old,'G010-CHANGE');const rv=revalidate(old,changed,'G010-REVAL');const currentId=rv.queue_ledger.current_request_index[Object.keys(rv.queue_ledger.current_request_index)[0]];const snap=rv.queue_ledger.decision_request_snapshots[currentId];const rr={resolution_request_id:'G010-RESOLVE',idempotency_key:'G010-RESOLVE-IDEM',author_actor_ref:'SYNTHETIC-AUTHOR',author_authority_proof_ref:'SYNTHETIC-PROOF',expected_parent_state_version:changed.parent.state_version,expected_parent_state_digest:changed.parent.state_digest,expected_queue_ledger_version:rv.queue_ledger.queue_ledger_version,expected_queue_ledger_digest:author.digestQueueLedger(rv.queue_ledger),decision_request_id:currentId,expected_decision_request_version:snap.decision_request_version,expected_decision_request_digest:author.digestDecisionRequest(snap),selected_option_id:'APPROVE',custom_author_choice:null,confirmation_evidence:{confirmed:true,decision_request_digest:author.digestDecisionRequest(snap),selected_option_identity:'OPTION:APPROVE',consequence_reviewed:false,confirmation_evidence_ref:'SYNTHETIC:G010'},rationale_optional:null,resolved_at:'2026-09-09T23:04:00Z'};expectError(()=>author.resolveDecision({parentState:changed.parent,versionLedger:changed.versionLedger,queueLedger:rv.queue_ledger,request:rr}),'AUTHOR_DECISION_SUBJECT_NOT_CURRENT');});
test('G011_CURRENT_SUBJECT_STILL_RESOLVES',()=>{const s=enqueue(authorSetup(),'G011');const rr=resolutionRequest(s,'G011');const out=author.resolveDecision({parentState:s.parent,versionLedger:s.versionLedger,queueLedger:s.queueLedger,request:rr});assert(out.disposition==='RESOLVED'&&out.author_decision.status==='APPROVED','CURRENT_RESOLUTION_FAIL');});
test('G012_AUTHOR_GUARD_SYNTHESIZES_NO_REAL_AUTHORITY',()=>{const s=enqueue(authorSetup(),'G012');const rr=resolutionRequest(s,'G012');const out=author.resolveDecision({parentState:s.parent,versionLedger:s.versionLedger,queueLedger:s.queueLedger,request:rr});assert(out.author_decision.author_choice==='APPROVE','CHOICE_CHANGED');assert(rr.author_actor_ref.startsWith('SYNTHETIC-')&&rr.author_authority_proof_ref.startsWith('SYNTHETIC-'),'FIXTURE_NOT_SYNTHETIC');assert(out.parent_state.book_project.status==='AUTHOR_REVIEW','AUTHOR_GUARD_CHANGED_LIFECYCLE');});
test('G013_EMPTY_PARENT_ADMISSION_REFS_REJECTED',()=>{const s=freezeSetup(),r=freezeRequest(s,'G013');r.parent_admission_refs=[];expectError(()=>freeze.freezeExport({parentState:s.parent,freezeLedger:s.ledger,request:r}),'PARENT_ADMISSION_REF_REQUIRED');});
test('G014_DUPLICATE_PARENT_ADMISSION_REFS_REJECTED',()=>{const s=freezeSetup(),r=freezeRequest(s,'G014');r.parent_admission_refs=['PROPOSAL-DOCUMENT-001','PROPOSAL-DOCUMENT-001'];expectError(()=>freeze.freezeExport({parentState:s.parent,freezeLedger:s.ledger,request:r}),'DUPLICATE_PARENT_ADMISSION_REF');});
test('G015_VALID_ADMISSION_DELEGATES_TO_EXPORT_FREEZE_V1',()=>{const s=freezeSetup(),r=freezeRequest(s,'G015');const out=freeze.freezeExport({parentState:s.parent,freezeLedger:s.ledger,request:r});assert(out.disposition==='COMMITTED'&&out.release.parent_admission_refs[0]==='PROPOSAL-DOCUMENT-001','VALID_FREEZE_NOT_DELEGATED');});
test('G016_NONADMITTED_PARENT_REF_STILL_REJECTED_BY_V1',()=>{const s=freezeSetup(),r=freezeRequest(s,'G016');r.parent_admission_refs=['MISSING-PROPOSAL'];expectError(()=>freeze.freezeExport({parentState:s.parent,freezeLedger:s.ledger,request:r}),'PARENT_ADMISSION_REF_NOT_FOUND');});
test('G017_AUTHOR_REFS_NOT_UNIVERSALLY_MADE_MANDATORY',()=>{const s=freezeSetup(),r=freezeRequest(s,'G017');r.author_decision_refs=[];const out=freeze.freezeExport({parentState:s.parent,freezeLedger:s.ledger,request:r});assert(out.disposition==='COMMITTED'&&out.release.author_decision_refs.length===0,'AUTHOR_REQUIREMENT_WIDENED');});
test('G018_SUPPLIED_AUTHOR_REF_STILL_VALIDATED_BY_V1',()=>{const s=freezeSetup(),r=freezeRequest(s,'G018');r.author_decision_refs=['MISSING-DECISION'];expectError(()=>freeze.freezeExport({parentState:s.parent,freezeLedger:s.ledger,request:r}),'AUTHOR_DECISION_REF_NOT_FOUND');});
test('G019_TECHNICAL_SUCCESS_WITHOUT_PARENT_ADMISSION_CANNOT_FREEZE',()=>{const s=freezeSetup(),r=freezeRequest(s,'G019');r.parent_admission_refs=[];assert(r.target_medium_evidence.proof_result==='PASS'&&r.provenance_evidence.validation_result==='PASS','TECHNICAL_SETUP_FAIL');expectError(()=>freeze.freezeExport({parentState:s.parent,freezeLedger:s.ledger,request:r}),'PARENT_ADMISSION_REF_REQUIRED');});
test('G020_FREEZE_GUARD_PRESERVES_LIFECYCLE_AND_PUBLICATION_BOUNDARY',()=>{const s=freezeSetup(),r=freezeRequest(s,'G020');const out=freeze.freezeExport({parentState:s.parent,freezeLedger:s.ledger,request:r});assert(out.parent_state.book_project.status==='FINALIZATION','FREEZE_GUARD_CHANGED_LIFECYCLE');assert(out.release.publication_authority_state==='NOT_AUTHORIZED','FREEZE_GUARD_AUTHORIZED_PUBLICATION');});
test('G021_FREEZE_GUARD_REPLAY_DOES_NOT_DUPLICATE_RELEASE',()=>{const s=freezeSetup(),r=freezeRequest(s,'G021');const first=freeze.freezeExport({parentState:s.parent,freezeLedger:s.ledger,request:r});const second=freeze.freezeExport({parentState:first.parent_state,freezeLedger:first.freeze_ledger,request:r});assert(second.disposition==='REPLAY'&&second.parent_state.export_releases.length===1,'FREEZE_REPLAY_DUPLICATED');});
test('G022_FREEZE_GUARD_FAILURE_PRESERVES_INPUT',()=>{const s=freezeSetup(),r=freezeRequest(s,'G022');r.parent_admission_refs=[];const pd=s.parent.state_digest,ld=freeze.digestFreezeLedger(s.ledger);expectError(()=>freeze.freezeExport({parentState:s.parent,freezeLedger:s.ledger,request:r}),'PARENT_ADMISSION_REF_REQUIRED');assert(s.parent.state_digest===pd&&freeze.digestFreezeLedger(s.ledger)===ld,'FREEZE_GUARD_MUTATED_INPUT');});
test('G023_BASE_AUTHOR_QUEUE_STILL_EXPOSES_NO_PROVIDER_RESOLVER',()=>{for(const name of ['providerResolve','modelResolve','autoResolve','timeoutResolve'])assert(typeof baseAuthor[name]==='undefined','BASE_AUTHOR_AUTHORITY_WIDENED',name);});
test('G024_EXACT_SHA_QUALIFICATION_DOES_NOT_TRANSFER',()=>{const h=head();assert(h!=='9601ae5df8348c1daac8805eaefa1718c431dd49'&&h!=='0bc1f96ed0b8effd22c432a7d727fd13d613b825','SUBJECT_EQUALS_PREDECESSOR');assert(contract.qualification_effect.includes('NONE_UNTIL'),'TRANSFER_RULE_MISSING');});

const ids=Object.keys(tests);const results=[];let failCount=0;for(const id of ids){try{tests[id]();results.push({id,result:'PASS'});}catch(e){results.push({id,result:'FAIL',code:e&&e.code||'ERROR',detail:e&&e.message||String(e)});failCount++;}}
const summary={qualification_id:contract.qualification_id,subject_sha:head(),case_count:ids.length,pass_count:ids.length-failCount,fail_count:failCount,result_class:failCount===0?'PASS':'FAIL',standing:'BOUNDED_REPAIR_QUALIFICATION_ONLY__NO_AUTHOR_FREEZE_PUBLICATION_OR_PRODUCTION_AUTHORITY',predecessor_subjects:{author_decision_queue_v1:'9601ae5df8348c1daac8805eaefa1718c431dd49',export_freeze_v1:'0bc1f96ed0b8effd22c432a7d727fd13d613b825'},authority:{new_author_authority:false,new_provider_authority:false,new_lifecycle_policy:false,new_document_authority:false,new_publication_authority:false},files:{contract_sha256:fileSha(rel.contract),author_guard_sha256:fileSha(rel.authorGuard),freeze_guard_sha256:fileSha(rel.exportGuard),qualifier_sha256:fileSha(rel.qualifier)},results};
write('summary.json',summary);write('cases.json',results);write('result.txt',`result=${summary.result_class}\npass_count=${summary.pass_count}\nfail_count=${summary.fail_count}\nsubject_sha=${summary.subject_sha}\n`);console.log(JSON.stringify(summary,null,2));if(failCount)process.exit(1);
